package main

import (
	"bytes"
	"crypto/rand"
	"encoding/gob"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"time"
)

type Repo struct {
	Path string
}

func (r Repo) gitDir() string {
	return filepath.Join(r.Path, ".git")
}

func (r Repo) dstaskDir() string {
	return filepath.Join(r.gitDir(), "dstask")
}

func (r Repo) statePath() string {
	return filepath.Join(r.dstackDirFallback(), "state.bin")
}

func (r Repo) idsPath() string {
	return filepath.Join(r.dstackDirFallback(), "ids.bin")
}

func (r Repo) dstackDirFallback() string {
	return filepath.Join(r.gitDir(), "dstask")
}

func (r Repo) exists() bool {
	info, err := os.Stat(r.gitDir())
	return err == nil && info.IsDir()
}

func (r Repo) ensure(autoInit bool) error {
	if r.exists() {
		return os.MkdirAll(r.dstackDirFallback(), 0o755)
	}
	if !autoInit {
		return nil
	}
	if err := os.MkdirAll(r.Path, 0o755); err != nil {
		return err
	}
	cmd := exec.Command("git", "init")
	cmd.Dir = r.Path
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}
	if _, err := fmt.Fprint(os.Stdout, "\nAdd a remote repository with:\n\n\tdstask git remote add origin <repo>\n\n"); err != nil {
		return err
	}
	return os.MkdirAll(r.dstackDirFallback(), 0o755)
}

func (r Repo) loadState() Query {
	envContext := os.Getenv("DSTASK_CONTEXT")
	if envContext != "" {
		return parseFilter(strings.Fields(envContext), false, false)
	}
	data, err := os.ReadFile(r.statePath())
	if err != nil {
		return Query{}
	}
	var state State
	if err := gob.NewDecoder(bytes.NewReader(data)).Decode(&state); err != nil {
		return Query{}
	}
	return state.Context
}

func (r Repo) saveState(q Query) error {
	if err := os.MkdirAll(r.dstackDirFallback(), 0o755); err != nil {
		return err
	}
	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(State{Context: q}); err != nil {
		return err
	}
	return os.WriteFile(r.statePath(), buf.Bytes(), 0o644)
}

func (r Repo) loadTasks() ([]*Task, error) {
	var tasks []*Task
	for _, status := range []string{"pending", "active", "paused", "resolved", "template"} {
		dir := filepath.Join(r.Path, status)
		entries, err := os.ReadDir(dir)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, err
		}
		for _, entry := range entries {
			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".yml") {
				continue
			}
			fullPath := filepath.Join(dir, entry.Name())
			data, err := os.ReadFile(fullPath)
			if err != nil {
				return nil, err
			}
			task, err := parseTaskYAML(data)
			if err != nil {
				return nil, err
			}
			task.Status = status
			task.UUID = strings.TrimSuffix(entry.Name(), ".yml")
			tasks = append(tasks, task)
		}
	}
	return tasks, nil
}

func (r Repo) loadIDs(tasks []*Task) (IdsMap, error) {
	ids := IdsMap{}
	data, err := os.ReadFile(r.idsPath())
	if err == nil {
		if err := gob.NewDecoder(bytes.NewReader(data)).Decode(&ids); err != nil {
			ids = IdsMap{}
		}
	}

	current := make(map[string]*Task)
	for _, task := range tasks {
		if task.Status != "resolved" {
			current[task.UUID] = task
		}
	}

	clean := IdsMap{}
	used := make(map[int]bool)
	for uuid, id := range ids {
		if id <= 0 {
			continue
		}
		if _, ok := current[uuid]; !ok {
			continue
		}
		if used[id] {
			continue
		}
		used[id] = true
		clean[uuid] = id
	}

	var missing []*Task
	for uuid, task := range current {
		if _, ok := clean[uuid]; !ok {
			missing = append(missing, task)
		}
	}
	sort.Slice(missing, func(i, j int) bool {
		if !missing[i].Created.Equal(missing[j].Created) {
			return missing[i].Created.Before(missing[j].Created)
		}
		return missing[i].UUID < missing[j].UUID
	})
	nextID := 1
	for _, task := range missing {
		for used[nextID] {
			nextID++
		}
		clean[task.UUID] = nextID
		used[nextID] = true
		nextID++
	}

	for _, task := range tasks {
		if id, ok := clean[task.UUID]; ok && task.Status != "resolved" {
			task.ID = id
		}
		if task.Status == "resolved" {
			task.ID = 0
		}
	}

	if err := r.saveIDs(clean); err != nil {
		return nil, err
	}
	return clean, nil
}

func (r Repo) saveIDs(ids IdsMap) error {
	if err := os.MkdirAll(r.dstackDirFallback(), 0o755); err != nil {
		return err
	}
	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(ids); err != nil {
		return err
	}
	return os.WriteFile(r.idsPath(), buf.Bytes(), 0o644)
}

func (r Repo) taskPath(task *Task) string {
	return filepath.Join(r.Path, statusDir(task.Status), task.UUID+".yml")
}

func (r Repo) writeTask(task *Task) error {
	dir := filepath.Join(r.Path, statusDir(task.Status))
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(r.taskPath(task), renderTaskYAML(task), 0o644)
}

func (r Repo) removeTask(task *Task) error {
	if err := os.Remove(r.taskPath(task)); err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

func (r Repo) moveTask(task *Task, oldStatus string) error {
	oldPath := filepath.Join(r.Path, statusDir(oldStatus), task.UUID+".yml")
	if oldPath == r.taskPath(task) {
		return r.writeTask(task)
	}
	if err := os.MkdirAll(filepath.Dir(r.taskPath(task)), 0o755); err != nil {
		return err
	}
	if err := os.Rename(oldPath, r.taskPath(task)); err == nil {
		return nil
	}
	if err := r.writeTask(task); err != nil {
		return err
	}
	if err := os.Remove(oldPath); err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

func (r Repo) gitCommit(message string) (string, error) {
	if _, err := r.runGitQuiet("add", "-A"); err != nil {
		return "", err
	}
	return r.runGit("commit", "-m", message, "--no-gpg-sign")
}

func (r Repo) runGit(args ...string) (string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = r.Path
	cmd.Env = append(os.Environ(), gitIdentityEnv()...)
	out, err := cmd.CombinedOutput()
	return string(out), err
}

func (r Repo) runGitQuiet(args ...string) (string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = r.Path
	cmd.Env = append(os.Environ(), gitIdentityEnv()...)
	out, err := cmd.CombinedOutput()
	return string(out), err
}

func gitIdentityEnv() []string {
	return []string{
		"GIT_AUTHOR_NAME=dstask",
		"GIT_AUTHOR_EMAIL=dstask@example.invalid",
		"GIT_COMMITTER_NAME=dstask",
		"GIT_COMMITTER_EMAIL=dstask@example.invalid",
	}
}

func findTaskByID(tasks []*Task, id int) *Task {
	for _, task := range tasks {
		if task.ID == id {
			return task
		}
	}
	return nil
}

func filterTasks(tasks []*Task, statuses map[string]bool, q Query) []*Task {
	var out []*Task
	for _, task := range tasks {
		if len(statuses) > 0 && !statuses[task.Status] {
			continue
		}
		if matchesQuery(task, q) {
			out = append(out, task)
		}
	}
	if statuses["resolved"] && len(statuses) == 1 {
		sortResolvedTasks(out)
	} else {
		sortOpenTasks(out)
	}
	return out
}

func buildTask(base *Task, context Query, q Query, status string, preserveCreated bool) *Task {
	task := &Task{
		Priority:     "P2",
		DelegatedTo:  "",
		Subtasks:     []string{},
		Dependencies: []string{},
		Created:      time.Now().UTC(),
		Resolved:     zeroTime(),
		Due:          zeroTime(),
		Tags:         []string{},
	}
	if base != nil {
		task = copyTask(base)
	}
	if !preserveCreated || base == nil {
		task.Created = time.Now().UTC()
	}
	if base == nil {
		task.Resolved = zeroTime()
		if task.Due.IsZero() {
			task.Due = zeroTime()
		}
	}
	applyContextToTask(task, context)
	applyCreateQuery(task, q)
	task.Status = status
	if task.Priority == "" {
		task.Priority = "P2"
	}
	if status != "resolved" {
		task.Resolved = zeroTime()
	}
	return task
}

func parseTaskYAML(data []byte) (*Task, error) {
	task := &Task{
		Tags:         []string{},
		Subtasks:     []string{},
		Dependencies: []string{},
		DelegatedTo:  "",
		Project:      "",
		Priority:     "P2",
		Notes:        "",
		Due:          zeroTime(),
		Resolved:     zeroTime(),
	}
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if strings.TrimSpace(line) == "" {
			continue
		}
		switch {
		case strings.HasPrefix(line, "summary:"):
			task.Summary = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "summary:")))
		case strings.HasPrefix(line, "notes:"):
			rest := strings.TrimSpace(strings.TrimPrefix(line, "notes:"))
			if strings.HasPrefix(rest, "|") {
				i++
				var noteLines []string
				for i < len(lines) {
					if strings.HasPrefix(lines[i], "  ") {
						noteLines = append(noteLines, strings.TrimPrefix(lines[i], "  "))
						i++
						continue
					}
					if lines[i] == "" {
						noteLines = append(noteLines, "")
						i++
						continue
					}
					i--
					break
				}
				task.Notes = strings.Join(noteLines, "\n")
			} else {
				task.Notes = parseScalar(rest)
			}
		case strings.HasPrefix(line, "tags:"):
			rest := strings.TrimSpace(strings.TrimPrefix(line, "tags:"))
			if rest == "[]" {
				task.Tags = []string{}
				continue
			}
			var tags []string
			for i+1 < len(lines) && strings.HasPrefix(lines[i+1], "- ") {
				i++
				tags = append(tags, strings.TrimPrefix(lines[i], "- "))
			}
			task.Tags = tags
		case strings.HasPrefix(line, "project:"):
			task.Project = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "project:")))
		case strings.HasPrefix(line, "priority:"):
			task.Priority = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "priority:")))
		case strings.HasPrefix(line, "delegatedto:"):
			task.DelegatedTo = parseScalar(strings.TrimSpace(strings.TrimPrefix(line, "delegatedto:")))
		case strings.HasPrefix(line, "subtasks:"):
			task.Subtasks = parseInlineList(strings.TrimSpace(strings.TrimPrefix(line, "subtasks:")))
		case strings.HasPrefix(line, "dependencies:"):
			task.Dependencies = parseInlineList(strings.TrimSpace(strings.TrimPrefix(line, "dependencies:")))
		case strings.HasPrefix(line, "created:"):
			task.Created = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "created:")))
		case strings.HasPrefix(line, "resolved:"):
			task.Resolved = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "resolved:")))
		case strings.HasPrefix(line, "due:"):
			task.Due = parseTime(strings.TrimSpace(strings.TrimPrefix(line, "due:")))
		}
	}
	return task, nil
}

func parseScalar(s string) string {
	if s == `""` {
		return ""
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		unquoted, err := strconv.Unquote(s)
		if err == nil {
			return unquoted
		}
	}
	return s
}

func parseInlineList(s string) []string {
	if s == "[]" {
		return []string{}
	}
	return []string{}
}

func parseTime(s string) time.Time {
	if s == "" {
		return zeroTime()
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return zeroTime()
	}
	return t.UTC()
}

func renderTaskYAML(task *Task) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "summary: %s\n", yamlScalar(task.Summary))
	writeNotes(&b, task.Notes)
	writeStringList(&b, "tags", task.Tags)
	fmt.Fprintf(&b, "project: %s\n", yamlScalar(task.Project))
	fmt.Fprintf(&b, "priority: %s\n", yamlScalar(task.Priority))
	fmt.Fprintf(&b, "delegatedto: %s\n", yamlScalar(task.DelegatedTo))
	fmt.Fprintf(&b, "subtasks: []\n")
	fmt.Fprintf(&b, "dependencies: []\n")
	fmt.Fprintf(&b, "created: %s\n", task.Created.UTC().Format(time.RFC3339Nano))
	fmt.Fprintf(&b, "resolved: %s\n", task.Resolved.UTC().Format(time.RFC3339Nano))
	fmt.Fprintf(&b, "due: %s\n", task.Due.UTC().Format(time.RFC3339Nano))
	return []byte(b.String())
}

func yamlScalar(value string) string {
	if value == "" {
		return `""`
	}
	if strings.ContainsAny(value, "\"\t\r") ||
		strings.Contains(value, ": ") ||
		strings.HasPrefix(value, "- ") ||
		strings.HasPrefix(value, "#") ||
		strings.HasPrefix(value, "[") ||
		strings.HasPrefix(value, "{") ||
		strings.HasPrefix(value, " ") ||
		strings.HasSuffix(value, " ") ||
		value == "null" ||
		value == "true" ||
		value == "false" {
		return strconv.Quote(value)
	}
	return value
}

func writeNotes(b *strings.Builder, notes string) {
	switch {
	case notes == "":
		fmt.Fprintf(b, "notes: %s\n", yamlScalar(notes))
	case strings.Contains(notes, "\n"):
		if strings.HasPrefix(notes, "\n") {
			fmt.Fprintf(b, "notes: |2-\n")
		} else {
			fmt.Fprintf(b, "notes: |-\n")
		}
		for _, line := range strings.Split(notes, "\n") {
			if line == "" {
				fmt.Fprintln(b)
			} else {
				fmt.Fprintf(b, "  %s\n", line)
			}
		}
	default:
		fmt.Fprintf(b, "notes: %s\n", yamlScalar(notes))
	}
}

func writeStringList(b *strings.Builder, key string, values []string) {
	if len(values) == 0 {
		fmt.Fprintf(b, "%s: []\n", key)
		return
	}
	fmt.Fprintf(b, "%s:\n", key)
	for _, value := range values {
		fmt.Fprintf(b, "- %s\n", value)
	}
}

func newUUID() string {
	var buf [16]byte
	if _, err := io.ReadFull(rand.Reader, buf[:]); err != nil {
		now := time.Now().UnixNano()
		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", now>>32, (now>>16)&0xffff, now&0xffff, now&0xffff, now)
	}
	buf[6] = (buf[6] & 0x0f) | 0x40
	buf[8] = (buf[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		uint32(buf[0])<<24|uint32(buf[1])<<16|uint32(buf[2])<<8|uint32(buf[3]),
		uint16(buf[4])<<8|uint16(buf[5]),
		uint16(buf[6])<<8|uint16(buf[7]),
		uint16(buf[8])<<8|uint16(buf[9]),
		buf[10:16],
	)
}

func tempEditPath(id int, summary, ext string) string {
	return filepath.Join(os.TempDir(), fmt.Sprintf("dstask.%d.%d-%s.%s", time.Now().UnixNano(), id, slugifySummary(summary), ext))
}

func runEditor(path string) error {
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		editor = "vi"
	}
	cmd := exec.Command(editor, path)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func openURL(url string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "windows":
		cmd = exec.Command("cmd", "/c", "start", url)
	default:
		cmd = exec.Command("xdg-open", url)
	}
	return cmd.Run()
}

