package main

import (
	"encoding/gob"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

type Task struct {
	UUID         string
	Status       string
	ID           int
	Summary      string
	Notes        string
	Tags         []string
	Project      string
	Priority     string
	DelegatedTo  string
	Subtasks     []string
	Dependencies []string
	Created      time.Time
	Resolved     time.Time
	Due          time.Time
}

type IdsMap map[string]int

type State struct {
	Context Query
}

type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      int
	Text          string
	IgnoreContext bool
	Note          string
}

type Parsed struct {
	Cmd      string
	IDs      []int
	Query    Query
	RawArgs  []string
	HelpName string
}

type ProjectSummary struct {
	Name          string    `json:"name"`
	TaskCount     int       `json:"taskCount"`
	ResolvedCount int       `json:"resolvedCount"`
	Active        bool      `json:"active"`
	Created       time.Time `json:"created"`
	Resolved      time.Time `json:"resolved"`
	Priority      string    `json:"priority"`
}

type jsonTask struct {
	UUID     string    `json:"uuid"`
	Status   string    `json:"status"`
	ID       int       `json:"id"`
	Summary  string    `json:"summary"`
	Notes    string    `json:"notes"`
	Tags     []string  `json:"tags"`
	Project  string    `json:"project"`
	Priority string    `json:"priority"`
	Created  time.Time `json:"created"`
	Resolved time.Time `json:"resolved"`
	Due      time.Time `json:"due"`
}

var commandAliases = map[string]string{
	"rm":        "remove",
	"notes":     "note",
	"resolve":   "done",
	"show-next": "next",
}

var knownCommands = map[string]bool{
	"add":              true,
	"bash-completion":  true,
	"context":          true,
	"done":             true,
	"edit":             true,
	"fish-completion":  true,
	"git":              true,
	"help":             true,
	"log":              true,
	"modify":           true,
	"next":             true,
	"note":             true,
	"open":             true,
	"remove":           true,
	"show-active":      true,
	"show-open":        true,
	"show-paused":      true,
	"show-projects":    true,
	"show-resolved":    true,
	"show-tags":        true,
	"show-templates":   true,
	"show-unorganised": true,
	"start":            true,
	"stop":             true,
	"sync":             true,
	"template":         true,
	"undo":             true,
	"version":          true,
	"zsh-completion":   true,
	"_completions":     true,
	"rm":               true,
	"notes":            true,
	"resolve":          true,
	"show-next":        true,
}

var urlRE = regexp.MustCompile(`https?://[^\s<>()]+`)

func init() {
	gob.Register(IdsMap{})
	gob.Register(State{})
	gob.Register(Query{})
}

func canonicalCommand(name string) string {
	if alias, ok := commandAliases[name]; ok {
		return alias
	}
	return name
}

func parseArgs(args []string) Parsed {
	if len(args) == 0 {
		return Parsed{Cmd: "next", Query: Query{Cmd: "next"}}
	}

	cmdIndex := -1
	cmdName := ""
	for i, arg := range args {
		if knownCommands[arg] {
			cmdIndex = i
			cmdName = canonicalCommand(arg)
			break
		}
	}

	if cmdIndex == -1 {
		q := parseFilter(args, true, false)
		q.Cmd = "next"
		return Parsed{
			Cmd:   "next",
			IDs:   q.IDs,
			Query: q,
		}
	}

	pre := args[:cmdIndex]
	post := args[cmdIndex+1:]

	idsBefore := intsFromTokens(pre)
	switch cmdName {
	case "help":
		helpName := ""
		if len(post) > 0 {
			helpName = canonicalCommand(post[0])
		}
		return Parsed{Cmd: "help", HelpName: helpName}
	case "version", "bash-completion", "fish-completion", "zsh-completion":
		return Parsed{Cmd: cmdName}
	case "_completions":
		return Parsed{Cmd: "_completions", RawArgs: post}
	case "git":
		return Parsed{Cmd: "git", RawArgs: post}
	case "context":
		q := Query{Cmd: "context", Text: strings.Join(post, " ")}
		return Parsed{Cmd: "context", Query: q}
	case "add":
		q := parseFilter(post, false, true)
		q.Cmd = "add"
		return Parsed{Cmd: "add", Query: q}
	case "log":
		q := parseFilter(post, false, true)
		q.Cmd = "log"
		return Parsed{Cmd: "log", Query: q}
	case "start":
		if len(idsBefore) > 0 {
			return Parsed{Cmd: "start", IDs: idsBefore, Query: Query{Cmd: "start"}}
		}
		ids, rest := splitLeadingInts(post)
		if len(ids) > 0 && len(rest) == 0 {
			return Parsed{Cmd: "start", IDs: ids, Query: Query{Cmd: "start"}}
		}
		q := parseFilter(post, false, true)
		q.Cmd = "start"
		return Parsed{Cmd: "start", Query: q}
	case "template":
		if len(idsBefore) > 0 {
			q := parseFilter(post, false, true)
			q.Cmd = "template"
			return Parsed{Cmd: "template", IDs: idsBefore, Query: q}
		}
		ids, rest := splitLeadingInts(post)
		if len(ids) > 0 {
			q := parseFilter(rest, false, true)
			q.Cmd = "template"
			return Parsed{Cmd: "template", IDs: ids, Query: q}
		}
		q := parseFilter(post, false, true)
		q.Cmd = "template"
		return Parsed{Cmd: "template", Query: q}
	case "stop", "done", "note":
		ids := idsBefore
		rest := post
		if len(ids) == 0 {
			ids, rest = splitLeadingInts(post)
		}
		q := Query{Cmd: cmdName}
		q.Note = strings.Join(rest, " ")
		return Parsed{Cmd: cmdName, IDs: ids, Query: q}
	case "edit", "open", "remove":
		ids := idsBefore
		if len(ids) == 0 {
			ids, _ = splitLeadingInts(post)
		}
		return Parsed{Cmd: cmdName, IDs: ids, Query: Query{Cmd: cmdName}}
	case "modify":
		ids := idsBefore
		rest := post
		if len(ids) == 0 {
			ids, rest = splitLeadingInts(post)
		}
		q := parseFilter(rest, false, false)
		q.Cmd = "modify"
		return Parsed{Cmd: "modify", IDs: ids, Query: q}
	case "show-projects", "show-tags", "show-active", "show-paused", "show-open", "show-resolved", "show-templates", "show-unorganised", "next":
		q := parseFilter(post, true, false)
		q.IDs = append([]int{}, idsBefore...)
		q.IDs = append(q.IDs, q.IDs[len(idsBefore):]...)
		if len(idsBefore) > 0 {
			seen := make(map[int]bool)
			var merged []int
			for _, id := range append(idsBefore, q.IDs[len(idsBefore):]...) {
				if !seen[id] {
					seen[id] = true
					merged = append(merged, id)
				}
			}
			q.IDs = merged
		}
		q.Cmd = cmdName
		return Parsed{Cmd: cmdName, IDs: q.IDs, Query: q}
	case "undo":
		q := Query{Cmd: "undo", Text: strings.Join(post, " ")}
		return Parsed{Cmd: "undo", Query: q}
	default:
		q := parseFilter(post, true, false)
		q.Cmd = cmdName
		return Parsed{Cmd: cmdName, IDs: idsBefore, Query: q}
	}
}

func parseFilter(tokens []string, allowIDs bool, allowSlash bool) Query {
	var q Query
	left := tokens
	if allowSlash {
		for i, tok := range tokens {
			if tok == "/" {
				left = tokens[:i]
				if i+1 < len(tokens) {
					q.Note = strings.Join(tokens[i+1:], " ")
				}
				break
			}
		}
	}

	var text []string
	for _, tok := range left {
		if tok == "--" {
			q.IgnoreContext = true
			continue
		}
		if allowIDs {
			if n, ok := parseInt(tok); ok {
				q.IDs = append(q.IDs, n)
				continue
			}
		}
		switch {
		case strings.HasPrefix(tok, "template:"):
			if n, ok := parseInt(strings.TrimPrefix(tok, "template:")); ok {
				q.Template = n
				continue
			}
		case tok == "P0" || tok == "P1" || tok == "P2" || tok == "P3":
			q.Priority = tok
			continue
		case strings.HasPrefix(tok, "-project:"):
			name := strings.TrimPrefix(tok, "-project:")
			if name != "" {
				q.AntiProjects = append(q.AntiProjects, name)
			}
			continue
		case strings.HasPrefix(tok, "project:"):
			name := strings.TrimPrefix(tok, "project:")
			if name != "" {
				q.Project = name
				continue
			}
		case strings.HasPrefix(tok, "due:"):
			if due, ok := parseDue(strings.TrimPrefix(tok, "due:")); ok {
				q.Due = due
				continue
			}
		case strings.HasPrefix(tok, "+") && len(tok) > 1:
			q.Tags = append(q.Tags, tok[1:])
			continue
		case strings.HasPrefix(tok, "-") && len(tok) > 1:
			q.AntiTags = append(q.AntiTags, tok[1:])
			continue
		}
		text = append(text, tok)
	}
	q.Text = strings.Join(text, " ")
	return q
}

func intsFromTokens(tokens []string) []int {
	var ids []int
	for _, tok := range tokens {
		if id, ok := parseInt(tok); ok {
			ids = append(ids, id)
		}
	}
	return ids
}

func splitLeadingInts(tokens []string) ([]int, []string) {
	var ids []int
	i := 0
	for i < len(tokens) {
		id, ok := parseInt(tokens[i])
		if !ok {
			break
		}
		ids = append(ids, id)
		i++
	}
	return ids, tokens[i:]
}

func parseInt(s string) (int, bool) {
	n, err := strconv.Atoi(s)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

func parseDue(s string) (time.Time, bool) {
	t, err := time.Parse("2006-01-02", s)
	if err != nil {
		return time.Time{}, false
	}
	return t.UTC(), true
}

func copyTask(t *Task) *Task {
	if t == nil {
		return nil
	}
	clone := *t
	clone.Tags = append([]string{}, t.Tags...)
	clone.Subtasks = append([]string{}, t.Subtasks...)
	clone.Dependencies = append([]string{}, t.Dependencies...)
	return &clone
}

func uniqueSortedStrings(values []string) []string {
	m := make(map[string]bool)
	for _, value := range values {
		if value != "" {
			m[value] = true
		}
	}
	out := make([]string, 0, len(m))
	for value := range m {
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func statusDir(status string) string {
	switch status {
	case "active", "paused", "pending", "resolved", "template":
		return status
	default:
		return "pending"
	}
}

func taskJSON(tasks []*Task) []byte {
	out := make([]jsonTask, 0, len(tasks))
	for _, task := range tasks {
		out = append(out, jsonTask{
			UUID:     task.UUID,
			Status:   task.Status,
			ID:       task.ID,
			Summary:  task.Summary,
			Notes:    task.Notes,
			Tags:     append([]string{}, task.Tags...),
			Project:  task.Project,
			Priority: task.Priority,
			Created:  task.Created,
			Resolved: task.Resolved,
			Due:      task.Due,
		})
	}
	data, _ := json.MarshalIndent(out, "", "  ")
	return data
}

func sortOpenTasks(tasks []*Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi := priorityRank(tasks[i].Priority)
		pj := priorityRank(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].UUID < tasks[j].UUID
	})
}

func sortResolvedTasks(tasks []*Task) {
	sort.Slice(tasks, func(i, j int) bool {
		if !tasks[i].Resolved.Equal(tasks[j].Resolved) {
			return tasks[i].Resolved.Before(tasks[j].Resolved)
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].UUID < tasks[j].UUID
	})
}

func priorityRank(priority string) int {
	switch priority {
	case "P0":
		return 0
	case "P1":
		return 1
	case "P2":
		return 2
	case "P3":
		return 3
	default:
		return 2
	}
}

func isInteractive() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	info, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (info.Mode() & os.ModeCharDevice) != 0
}

func slugifySummary(summary string) string {
	summary = strings.ToLower(summary)
	var b strings.Builder
	for _, r := range summary {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		default:
			b.WriteRune('-')
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return "task"
	}
	return out
}

func defaultRepoPath() string {
	if path := os.Getenv("DSTASK_GIT_REPO"); path != "" {
		return path
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return ".dstask"
	}
	return filepath.Join(home, ".dstask")
}

func queryString(q Query) string {
	if q.Text == "" && len(q.Tags) == 0 && len(q.AntiTags) == 0 && q.Project == "" && len(q.AntiProjects) == 0 && q.Priority == "" && q.Due.IsZero() {
		return ""
	}
	var parts []string
	for _, tag := range q.Tags {
		parts = append(parts, "+"+tag)
	}
	for _, tag := range q.AntiTags {
		parts = append(parts, "-"+tag)
	}
	if q.Project != "" {
		parts = append(parts, "project:"+q.Project)
	}
	for _, project := range q.AntiProjects {
		parts = append(parts, "-project:"+project)
	}
	if !q.Due.IsZero() {
		parts = append(parts, "due:"+q.Due.Format("2006-01-02"))
	}
	if q.Priority != "" {
		parts = append(parts, q.Priority)
	}
	if q.Text != "" {
		parts = append(parts, q.Text)
	}
	return strings.Join(parts, " ")
}

func mergeQuery(context Query, explicit Query) Query {
	if explicit.IgnoreContext {
		return explicit
	}
	merged := explicit
	merged.Tags = append(append([]string{}, context.Tags...), explicit.Tags...)
	merged.AntiTags = append(append([]string{}, context.AntiTags...), explicit.AntiTags...)
	merged.AntiProjects = append(append([]string{}, context.AntiProjects...), explicit.AntiProjects...)
	if merged.Project == "" {
		merged.Project = context.Project
	}
	if merged.Priority == "" {
		merged.Priority = context.Priority
	}
	if merged.Due.IsZero() {
		merged.Due = context.Due
	}
	if merged.Text == "" {
		merged.Text = context.Text
	} else if context.Text != "" {
		merged.Text = strings.TrimSpace(context.Text + " " + merged.Text)
	}
	return merged
}

func applyContextToTask(task *Task, context Query) {
	if context.Project != "" && task.Project == "" {
		task.Project = context.Project
	}
	for _, tag := range context.Tags {
		addTag(task, tag)
	}
}

func applyCreateQuery(task *Task, q Query) {
	for _, anti := range q.AntiTags {
		removeTag(task, anti)
	}
	for _, tag := range q.Tags {
		addTag(task, tag)
	}
	if q.Project != "" {
		task.Project = q.Project
	}
	for _, antiProject := range q.AntiProjects {
		if task.Project == antiProject {
			task.Project = ""
		}
	}
	if q.Priority != "" {
		task.Priority = q.Priority
	}
	if !q.Due.IsZero() {
		task.Due = q.Due
	}
	if q.Text != "" {
		task.Summary = q.Text
	}
	if q.Note != "" {
		if task.Notes == "" {
			task.Notes = q.Note
		} else {
			task.Notes = task.Notes + "\n" + q.Note
		}
	}
}

func addTag(task *Task, tag string) {
	for _, existing := range task.Tags {
		if existing == tag {
			return
		}
	}
	task.Tags = append(task.Tags, tag)
	sort.Strings(task.Tags)
}

func removeTag(task *Task, tag string) {
	var out []string
	for _, existing := range task.Tags {
		if existing != tag {
			out = append(out, existing)
		}
	}
	task.Tags = out
}

func matchesQuery(task *Task, q Query) bool {
	if len(q.IDs) > 0 {
		matched := false
		for _, id := range q.IDs {
			if task.ID == id {
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	if q.Project != "" && task.Project != q.Project {
		return false
	}
	if q.Priority != "" && task.Priority != q.Priority {
		return false
	}
	if !q.Due.IsZero() && !sameDay(task.Due, q.Due) {
		return false
	}
	for _, tag := range q.Tags {
		if !hasTag(task, tag) {
			return false
		}
	}
	for _, tag := range q.AntiTags {
		if hasTag(task, tag) {
			return false
		}
	}
	for _, project := range q.AntiProjects {
		if task.Project == project {
			return false
		}
	}
	if q.Text != "" {
		haystack := strings.ToLower(task.Summary + "\n" + task.Notes)
		if !strings.Contains(haystack, strings.ToLower(q.Text)) {
			return false
		}
	}
	return true
}

func sameDay(a, b time.Time) bool {
	if a.IsZero() || b.IsZero() {
		return a.IsZero() && b.IsZero()
	}
	ay, am, ad := a.Date()
	by, bm, bd := b.Date()
	return ay == by && am == bm && ad == bd
}

func hasTag(task *Task, tag string) bool {
	for _, existing := range task.Tags {
		if existing == tag {
			return true
		}
	}
	return false
}

func zeroTime() time.Time {
	return time.Time{}.UTC()
}

func idsFromMap(ids IdsMap) map[int]string {
	out := make(map[int]string)
	for uuid, id := range ids {
		out[id] = uuid
	}
	return out
}

func firstFreeID(ids IdsMap) int {
	used := idsFromMap(ids)
	for i := 1; ; i++ {
		if _, ok := used[i]; !ok {
			return i
		}
	}
}

func redError(message string) error {
	return errors.New("\x1b[31m" + message + "\x1b[0m")
}

func formatTaskLine(task *Task) string {
	return fmt.Sprintf("%d: %s", task.ID, task.Summary)
}

