package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"
)

func main() {
	parsed := parseArgs(os.Args[1:])

	switch parsed.Cmd {
	case "help":
		fmt.Print(helpTexts[parsed.HelpName])
		if parsed.HelpName == "" {
			return
		}
		if text, ok := helpTexts[parsed.HelpName]; ok {
			fmt.Print(text)
			return
		}
		fmt.Print(generalHelpText)
		return
	case "version":
		fmt.Print(versionText)
		return
	case "bash-completion":
		fmt.Print(bashCompletionScript)
		return
	case "fish-completion":
		fmt.Print(fishCompletionScript)
		return
	case "zsh-completion":
		fmt.Print(zshCompletionScript)
		return
	case "_completions":
		if err := runCompletions(parsed.RawArgs); err != nil {
			exitWithError(err)
		}
		return
	}

	repo := Repo{Path: defaultRepoPath()}
	if err := repo.ensure(true); err != nil {
		exitWithError(err)
	}

	context := repo.loadState()
	interactive := isInteractive()

	switch parsed.Cmd {
	case "context":
		if err := runContext(repo, parsed.Query); err != nil {
			exitWithError(err)
		}
	case "next", "show-open", "show-active", "show-paused", "show-resolved", "show-templates", "show-unorganised":
		if err := runTaskQuery(repo, parsed, context, interactive); err != nil {
			exitWithError(err)
		}
	case "show-tags":
		if err := runShowTags(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "show-projects":
		if err := runShowProjects(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "add":
		if err := runAdd(repo, parsed.Query, context); err != nil {
			exitWithError(err)
		}
	case "log":
		if err := runLog(repo, parsed.Query, context); err != nil {
			exitWithError(err)
		}
	case "template":
		if err := runTemplate(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "start":
		if err := runStart(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "stop":
		if err := runStop(repo, parsed); err != nil {
			exitWithError(err)
		}
	case "done":
		if err := runDone(repo, parsed); err != nil {
			exitWithError(err)
		}
	case "modify":
		if err := runModify(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "edit":
		if err := runEdit(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "note":
		if err := runNote(repo, parsed.IDs, parsed.Query.Note, interactive); err != nil {
			exitWithError(err)
		}
	case "open":
		if err := runOpen(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "remove":
		if err := runRemove(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "undo":
		if err := runUndo(repo, parsed.Query.Text); err != nil {
			exitWithError(err)
		}
	case "sync":
		if err := runSync(repo); err != nil {
			exitWithError(err)
		}
	case "git":
		if err := runGit(repo, parsed.RawArgs); err != nil {
			exitWithError(err)
		}
	default:
		if err := runTaskQuery(repo, Parsed{Cmd: "next", Query: parsed.Query}, context, interactive); err != nil {
			exitWithError(err)
		}
	}
}

func exitWithError(err error) {
	if err == nil {
		return
	}
	fmt.Fprintln(os.Stdout, err.Error())
	os.Exit(1)
}

func loadRepoTasks(repo Repo) ([]*Task, IdsMap, error) {
	tasks, err := repo.loadTasks()
	if err != nil {
		return nil, nil, err
	}
	ids, err := repo.loadIDs(tasks)
	if err != nil {
		return nil, nil, err
	}
	return tasks, ids, nil
}

func runContext(repo Repo, q Query) error {
	text := strings.TrimSpace(q.Text)
	switch text {
	case "":
		fmt.Println(queryString(repo.loadState()))
		return nil
	case "none", "--":
		return repo.saveState(Query{})
	default:
		return repo.saveState(parseFilter(strings.Fields(text), false, false))
	}
}

func runTaskQuery(repo Repo, parsed Parsed, context Query, interactive bool) error {
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	query := mergeQuery(context, parsed.Query)
	statuses := map[string]bool{}
	switch parsed.Cmd {
	case "show-active":
		statuses["active"] = true
	case "show-paused":
		statuses["paused"] = true
	case "show-resolved":
		statuses["resolved"] = true
	case "show-templates":
		statuses["template"] = true
	case "show-unorganised":
		statuses["pending"] = true
		statuses["active"] = true
		statuses["paused"] = true
	default:
		statuses["pending"] = true
		statuses["active"] = true
		statuses["paused"] = true
	}
	filtered := filterTasks(tasks, statuses, query)
	if parsed.Cmd == "show-unorganised" {
		var unorganised []*Task
		for _, task := range filtered {
			if len(task.Tags) == 0 && task.Project == "" {
				unorganised = append(unorganised, task)
			}
		}
		filtered = unorganised
	}
	if interactive {
		printTasksTTY(filtered)
		return nil
	}
	_, err = os.Stdout.Write(taskJSON(filtered))
	return err
}

func runShowTags(repo Repo, parsed Parsed, context Query) error {
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	query := mergeQuery(context, parsed.Query)
	filtered := filterTasks(tasks, map[string]bool{"pending": true, "active": true, "paused": true}, query)
	var tags []string
	for _, task := range filtered {
		tags = append(tags, task.Tags...)
	}
	tags = uniqueSortedStrings(tags)
	if len(tags) == 0 {
		return nil
	}
	fmt.Println(strings.Join(tags, "\n"))
	return nil
}

func runShowProjects(repo Repo, parsed Parsed, context Query) error {
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	query := mergeQuery(context, parsed.Query)
	filtered := filterTasks(tasks, map[string]bool{
		"pending":  true,
		"active":   true,
		"paused":   true,
		"resolved": true,
	}, query)
	projects := make(map[string]*ProjectSummary)
	for _, task := range filtered {
		if task.Project == "" {
			continue
		}
		ps := projects[task.Project]
		if ps == nil {
			ps = &ProjectSummary{
				Name:     task.Project,
				Created:  task.Created,
				Resolved: zeroTime(),
				Priority: task.Priority,
			}
			projects[task.Project] = ps
		}
		ps.TaskCount++
		if task.Status == "resolved" {
			ps.ResolvedCount++
			if ps.Resolved.IsZero() || ps.Resolved.Before(task.Resolved) {
				ps.Resolved = task.Resolved
			}
		} else {
			if priorityRank(task.Priority) < priorityRank(ps.Priority) {
				ps.Priority = task.Priority
			}
		}
		if task.Status == "active" {
			ps.Active = true
		}
		if task.Created.Before(ps.Created) {
			ps.Created = task.Created
		}
	}
	var out []ProjectSummary
	for _, ps := range projects {
		out = append(out, *ps)
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	data, _ := json.MarshalIndent(out, "", "  ")
	_, err = os.Stdout.Write(data)
	return err
}

func runAdd(repo Repo, q Query, context Query) error {
	tasks, ids, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	base, err := baseTaskForCreate(tasks, q.Template)
	if err != nil {
		return err
	}
	if strings.TrimSpace(q.Text) == "" && base == nil {
		return redError("task description or template required")
	}
	task := buildTask(base, contextIfNeeded(context, q), q, "pending", false)
	task.UUID = newUUID()
	task.Status = "pending"
	task.ID = firstFreeID(ids)
	ids[task.UUID] = task.ID
	if err := repo.writeTask(task); err != nil {
		return err
	}
	if err := repo.saveIDs(ids); err != nil {
		return err
	}
	commitMsg := fmt.Sprintf("Added %d: %s", task.ID, task.Summary)
	fmt.Printf("\n%s\n", commitMsg)
	out, err := repo.gitCommit(commitMsg)
	if err != nil {
		return err
	}
	fmt.Print("\x1b[38;5;245m" + out + "\x1b[0m")
	return nil
}

func runLog(repo Repo, q Query, context Query) error {
	if strings.TrimSpace(q.Text) == "" {
