func runUndo(repo Repo, text string) error {
	n := 1
	if strings.TrimSpace(text) != "" {
		parsed, err := strconv.Atoi(strings.TrimSpace(text))
		if err == nil && parsed > 0 {
			n = parsed
		}
	}
	var out string
	var err error
	if n == 1 {
		out, err = repo.runGit("revert", "--no-edit", "HEAD")
	} else {
		rangeSpec := fmt.Sprintf("HEAD~%d..HEAD", n)
		out, err = repo.runGit("revert", "--no-edit", rangeSpec)
	}
	fmt.Print(out)
	if err != nil {
		return err
	}
	tasks, ids, loadErr := loadRepoTasks(repo)
	if loadErr == nil {
		_ = tasks
		_ = repo.saveIDs(ids)
	}
	return nil
}

