		if i%2 == 1 {
			color = "\x1b[0;38;5;250;48;5;232m"
		}
		due := ""
		if !task.Due.IsZero() {
			due = task.Due.Format("2006-01-02")
		}
		fmt.Printf("%s%-3d %-9s %-4s %-10s %-8s %s\x1b[0m\n", color, task.ID, task.Priority, strings.Join(task.Tags, ","), due, task.Project, task.Summary)
	}
	fmt.Printf("\n%d tasks.\n", len(tasks))
