func printTaskDetailTTY(task *Task) {
	rows := [][2]string{
		{"ID", fmt.Sprintf("%d", task.ID)},
		{"Priority", task.Priority},
		{"Summary", task.Summary},
		{"Status", task.Status},
		{"Project", task.Project},
		{"Tags", strings.Join(task.Tags, ", ")},
		{"UUID", task.UUID},
		{"Created", task.Created.String()},
	}
	fmt.Print("\x1b[4;38;5;250;48;5;232mName      Value                                  \x1b[0m\n")
	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	for i, row := range rows {
		color := "\x1b[0;38;5;250;48;5;233m"
		if i%2 == 1 {
			color = "\x1b[0;38;5;250;48;5;232m"
		}
		fmt.Fprintf(tw, "%s%-8s\t%s\x1b[0m\n", color, row[0], row[1])
	}
	_ = tw.Flush()
	if task.Notes != "" {
		fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\n\x1b[0m\n", task.ID, task.Notes)
	} else {
		fmt.Println()
	}
}

