		q := parseFilter(post, true, false)
		q.Cmd = cmdName
		return Parsed{Cmd: cmdName, IDs: idsBefore, Query: q}
	}
}

func parseFilter(tokens []string, allowIDs bool, allowSlash bool) Query {
	var q Query
	left := tokens
	if allowSlash {
		for i, tok := range tokens {
			if tok == "/" {
				left = tokens[:i]
				if i+1 < len(tokens) {
					q.Note = strings.Join(tokens[i+1:], " ")
				}
				break
			}
		}
	}

	var text []string
	for _, tok := range left {
		if tok == "--" {
			q.IgnoreContext = true
			continue
		}
		if allowIDs {
			if n, ok := parseInt(tok); ok {
				q.IDs = append(q.IDs, n)
				continue
			}
		}
		switch {
		case strings.HasPrefix(tok, "template:"):
			if n, ok := parseInt(strings.TrimPrefix(tok, "template:")); ok {
				q.Template = n
				continue
			}
		case tok == "P0" || tok == "P1" || tok == "P2" || tok == "P3":
			q.Priority = tok
			continue
		case strings.HasPrefix(tok, "-project:"):
			name := strings.TrimPrefix(tok, "-project:")
			if name != "" {
				q.AntiProjects = append(q.AntiProjects, name)
			}
			continue
		case strings.HasPrefix(tok, "project:"):
			name := strings.TrimPrefix(tok, "project:")
			if name != "" {
				q.Project = name
				continue
			}
		case strings.HasPrefix(tok, "due:"):
			if due, ok := parseDue(strings.TrimPrefix(tok, "due:")); ok {
				q.Due = due
				continue
			}
		case strings.HasPrefix(tok, "+") && len(tok) > 1:
			q.Tags = append(q.Tags, tok[1:])
			continue
		case strings.HasPrefix(tok, "-") && len(tok) > 1:
			q.AntiTags = append(q.AntiTags, tok[1:])
			continue
		}
		text = append(text, tok)
	}
	q.Text = strings.Join(text, " ")
	return q
}

func intsFromTokens(tokens []string) []int {
	var ids []int
	for _, tok := range tokens {
		if id, ok := parseInt(tok); ok {
			ids = append(ids, id)
		}
	}
	return ids
}

func splitLeadingInts(tokens []string) ([]int, []string) {
	var ids []int
	i := 0
	for i < len(tokens) {
		id, ok := parseInt(tokens[i])
		if !ok {
			break
		}
		ids = append(ids, id)
		i++
	}
	return ids, tokens[i:]
}

func parseInt(s string) (int, bool) {
	n, err := strconv.Atoi(s)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

func parseDue(s string) (time.Time, bool) {
	t, err := time.Parse("2006-01-02", s)
	if err != nil {
		return time.Time{}, false
	}
	return t.UTC(), true
}

func copyTask(t *Task) *Task {
	if t == nil {
		return nil
	}
	clone := *t
	clone.Tags = append([]string{}, t.Tags...)
	clone.Subtasks = append([]string{}, t.Subtasks...)
	clone.Dependencies = append([]string{}, t.Dependencies...)
	return &clone
}

func uniqueSortedStrings(values []string) []string {
	m := make(map[string]bool)
	for _, value := range values {
		if value != "" {
			m[value] = true
		}
	}
	out := make([]string, 0, len(m))
	for value := range m {
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func statusDir(status string) string {
	switch status {
	case "active", "paused", "pending", "resolved", "template":
		return status
	default:
		return "pending"
	}
}

func taskJSON(tasks []*Task) []byte {
	out := make([]jsonTask, 0, len(tasks))
	for _, task := range tasks {
		out = append(out, jsonTask{
			UUID:     task.UUID,
			Status:   task.Status,
			ID:       task.ID,
			Summary:  task.Summary,
			Notes:    task.Notes,
			Tags:     append([]string{}, task.Tags...),
			Project:  task.Project,
			Priority: task.Priority,
			Created:  task.Created,
			Resolved: task.Resolved,
			Due:      task.Due,
		})
	}
	data, _ := json.MarshalIndent(out, "", "  ")
	return data
}

func sortOpenTasks(tasks []*Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi := priorityRank(tasks[i].Priority)
		pj := priorityRank(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].UUID < tasks[j].UUID
	})
}

func sortResolvedTasks(tasks []*Task) {
	sort.Slice(tasks, func(i, j int) bool {
		if !tasks[i].Resolved.Equal(tasks[j].Resolved) {
			return tasks[i].Resolved.Before(tasks[j].Resolved)
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
			return tasks[i].Created.Before(tasks[j].Created)
		}
		return tasks[i].UUID < tasks[j].UUID
	})
}

func priorityRank(priority string) int {
	switch priority {
	case "P0":
		return 0
	case "P1":
		return 1
	case "P2":
		return 2
	case "P3":
		return 3
	default:
		return 2
	}
}

func isInteractive() bool {
	if os.Getenv("DSTASK_FAKE_PTY") != "" {
		return true
	}
	info, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (info.Mode() & os.ModeCharDevice) != 0
}

func slugifySummary(summary string) string {
	summary = strings.ToLower(summary)
	var b strings.Builder
	for _, r := range summary {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		default:
			b.WriteRune('-')
		}
	}
	out := strings.Trim(b.String(), "-")
	if out == "" {
		return "task"
	}
	return out
}

func defaultRepoPath() string {
	if path := os.Getenv("DSTASK_GIT_REPO"); path != "" {
		return path
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return ".dstask"
	}
	return filepath.Join(home, ".dstask")
}

