package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"
)

func main() {
	parsed := parseArgs(os.Args[1:])

	switch parsed.Cmd {
	case "help":
		if parsed.HelpName == "" {
			fmt.Print(generalHelpText)
			return
		}
		if text, ok := helpTexts[parsed.HelpName]; ok {
			fmt.Print(text)
			return
		}
		fmt.Print(generalHelpText)
		return
	case "version":
		fmt.Print(versionText)
		return
	case "bash-completion":
		fmt.Print(bashCompletionScript)
		return
	case "fish-completion":
		fmt.Print(fishCompletionScript)
		return
	case "zsh-completion":
		fmt.Print(zshCompletionScript)
		return
	case "_completions":
		if err := runCompletions(parsed.RawArgs); err != nil {
			exitWithError(err)
		}
		return
	}

	repo := Repo{Path: defaultRepoPath()}
	if err := repo.ensure(true); err != nil {
		exitWithError(err)
	}

	context := repo.loadState()
	interactive := isInteractive()

	switch parsed.Cmd {
	case "context":
		if err := runContext(repo, parsed.Query); err != nil {
			exitWithError(err)
		}
	case "next", "show-open", "show-active", "show-paused", "show-resolved", "show-templates", "show-unorganised":
		if err := runTaskQuery(repo, parsed, context, interactive); err != nil {
			exitWithError(err)
		}
	case "show-tags":
		if err := runShowTags(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "show-projects":
		if err := runShowProjects(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "add":
		if err := runAdd(repo, parsed.Query, context); err != nil {
			exitWithError(err)
		}
	case "log":
		if err := runLog(repo, parsed.Query, context); err != nil {
			exitWithError(err)
		}
	case "template":
		if err := runTemplate(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "start":
		if err := runStart(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "stop":
		if err := runStop(repo, parsed); err != nil {
			exitWithError(err)
		}
	case "done":
		if err := runDone(repo, parsed); err != nil {
			exitWithError(err)
		}
	case "modify":
		if err := runModify(repo, parsed, context); err != nil {
			exitWithError(err)
		}
	case "edit":
		if err := runEdit(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "note":
		if err := runNote(repo, parsed.IDs, parsed.Query.Note, interactive); err != nil {
			exitWithError(err)
		}
	case "open":
		if err := runOpen(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "remove":
		if err := runRemove(repo, parsed.IDs); err != nil {
			exitWithError(err)
		}
	case "undo":
		if err := runUndo(repo, parsed.Query.Text); err != nil {
			exitWithError(err)
		}
	case "sync":
		if err := runSync(repo); err != nil {
			exitWithError(err)
		}
	case "git":
		if err := runGit(repo, parsed.RawArgs); err != nil {
			exitWithError(err)
		}
	default:
		if err := runTaskQuery(repo, Parsed{Cmd: "next", Query: parsed.Query}, context, interactive); err != nil {
			exitWithError(err)
		}
	}
}

func exitWithError(err error) {
	if err == nil {
		return
	}
	fmt.Fprintln(os.Stdout, err.Error())
	os.Exit(1)
}

