func runTaskQuery(repo Repo, parsed Parsed, context Query, interactive bool) error {
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	query := mergeQuery(context, parsed.Query)
	statuses := map[string]bool{}
	switch parsed.Cmd {
	case "show-active":
		statuses["active"] = true
	case "show-paused":
		statuses["paused"] = true
	case "show-resolved":
		statuses["resolved"] = true
	case "show-templates":
		statuses["template"] = true
	case "show-unorganised":
		statuses["pending"] = true
		statuses["active"] = true
		statuses["paused"] = true
	default:
		statuses["pending"] = true
		statuses["active"] = true
		statuses["paused"] = true
	}
	filtered := filterTasks(tasks, statuses, query)
	if parsed.Cmd == "show-unorganised" {
		var unorganised []*Task
		for _, task := range filtered {
			if len(task.Tags) == 0 && task.Project == "" {
				unorganised = append(unorganised, task)
			}
		}
		filtered = unorganised
	}
	if interactive {
		printTasksTTY(filtered)
		return nil
	}
	_, err = os.Stdout.Write(taskJSON(filtered))
	return err
}

