func runShowProjects(repo Repo, parsed Parsed, context Query) error {
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	query := mergeQuery(context, parsed.Query)
	filtered := filterTasks(tasks, map[string]bool{
		"pending":  true,
		"active":   true,
		"paused":   true,
		"resolved": true,
	}, query)
	projects := make(map[string]*ProjectSummary)
	openPrioritySeen := make(map[string]bool)
	for _, task := range filtered {
		if task.Project == "" {
			continue
		}
		ps := projects[task.Project]
		if ps == nil {
			ps = &ProjectSummary{
				Name:     task.Project,
				Created:  task.Created,
				Resolved: zeroTime(),
				Priority: task.Priority,
			}
			projects[task.Project] = ps
		}
		ps.TaskCount++
		if task.Status == "resolved" {
			ps.ResolvedCount++
			if ps.Resolved.IsZero() || ps.Resolved.Before(task.Resolved) {
				ps.Resolved = task.Resolved
			}
		} else {
			if !openPrioritySeen[task.Project] || priorityRank(task.Priority) < priorityRank(ps.Priority) {
				ps.Priority = task.Priority
			}
			openPrioritySeen[task.Project] = true
		}
		if task.Status == "active" {
			ps.Active = true
		}
		if task.Created.Before(ps.Created) {
			ps.Created = task.Created
		}
	}
	var out []ProjectSummary
	for _, ps := range projects {
		out = append(out, *ps)
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	data, _ := json.MarshalIndent(out, "", "  ")
	_, err = os.Stdout.Write(data)
	return err
}

