func runModify(repo Repo, parsed Parsed, context Query) error {
	if len(parsed.Query.Tags) == 0 && len(parsed.Query.AntiTags) == 0 && parsed.Query.Project == "" && len(parsed.Query.AntiProjects) == 0 && parsed.Query.Priority == "" {
		return redError("no operations specified")
	}
	tasks, _, err := loadRepoTasks(repo)
	if err != nil {
		return err
	}
	var selected []*Task
	if len(parsed.IDs) > 0 {
		for _, id := range parsed.IDs {
			task := findTaskByID(tasks, id)
			if task == nil {
				return redError(fmt.Sprintf("no open task with ID %d exists", id))
			}
			selected = append(selected, task)
		}
	} else {
		query := context
		if parsed.Query.IgnoreContext {
			query = Query{}
		}
		for _, task := range tasks {
			if task.Status == "resolved" {
				continue
			}
			if matchesQuery(task, query) {
				selected = append(selected, task)
			}
		}
	}
	for _, task := range selected {
		for _, tag := range parsed.Query.AntiTags {
			removeTag(task, tag)
		}
		for _, tag := range parsed.Query.Tags {
			addTag(task, tag)
		}
		if parsed.Query.Project != "" {
			task.Project = parsed.Query.Project
		}
		for _, antiProject := range parsed.Query.AntiProjects {
			if task.Project == antiProject {
				task.Project = ""
			}
		}
		if parsed.Query.Priority != "" {
			task.Priority = parsed.Query.Priority
		}
		if err := repo.writeTask(task); err != nil {
			return err
		}
		commitMsg := fmt.Sprintf("Modified %d: %s", task.ID, task.Summary)
		fmt.Printf("\n%s\n", commitMsg)
		out, err := repo.gitCommit(commitMsg)
		if err != nil {
			return err
		}
		fmt.Print("\x1b[38;5;245m" + out + "\x1b[0m")
	}
	return nil
}

