func runCompletions(args []string) error {
	last := ""
	if len(args) > 0 {
		last = args[len(args)-1]
	}
	if _, ok := parseInt(last); ok {
		return nil
	}
	items := append([]string{}, staticCompletionItems...)
	repo := Repo{Path: defaultRepoPath()}
	if repo.exists() {
		tasks, _, err := loadRepoTasks(repo)
		if err == nil {
			var projects []string
			var tags []string
			for _, task := range tasks {
				if task.Status == "resolved" {
					continue
				}
				if task.Project != "" {
					projects = append(projects, task.Project)
				}
				tags = append(tags, task.Tags...)
			}
			for _, project := range uniqueSortedStrings(projects) {
				items = append(items, "project:"+project, "-project:"+project)
			}
			for _, tag := range uniqueSortedStrings(tags) {
				items = append(items, "+"+tag, "-"+tag)
			}
		}
	}
	if len(args) > 1 {
		return nil
	}
	if last != "" && last != "dstask" {
		var filtered []string
		for _, item := range items {
			if strings.HasPrefix(item, last) {
				filtered = append(filtered, item)
			}
		}
		items = filtered
	}
	if len(items) == 0 {
		return nil
	}
	fmt.Println(strings.Join(items, "\n"))
	return nil
}

