func contextIfNeeded(context Query, q Query) Query {
	if q.IgnoreContext {
		return Query{}
	}
	return context
}

func printTasksTTY(tasks []*Task) {
	if len(tasks) == 0 {
		fmt.Println("No tasks found. Run `dstask help` for instructions.")
		return
	}
	if len(tasks) == 1 {
		printTaskDetailTTY(tasks[0])
		return
	}
	fmt.Print("\x1b[4;38;5;250;48;5;232mID  Priority  Tags  Due  Project  Summary\x1b[0m\n")
	for i, task := range tasks {
		color := "\x1b[0;38;5;250;48;5;233m"
		if i%2 == 1 {
			color = "\x1b[0;38;5;250;48;5;232m"
		}
		due := ""
		if !task.Due.IsZero() {
			due = task.Due.Format("2006-01-02")
		}
		fmt.Printf("%s%-3d %-9s %-4s %-10s %-8s %s\x1b[0m\n", color, task.ID, task.Priority, strings.Join(task.Tags, ","), due, task.Project, task.Summary)
	}
	fmt.Printf("\n%d tasks.\n", len(tasks))
}

func printTaskDetailTTY(task *Task) {
	rows := [][2]string{
		{"ID", fmt.Sprintf("%d", task.ID)},
		{"Priority", task.Priority},
		{"Summary", task.Summary},
		{"Status", task.Status},
		{"Project", task.Project},
		{"Tags", strings.Join(task.Tags, ", ")},
		{"UUID", task.UUID},
		{"Created", task.Created.String()},
	}
	fmt.Print("\x1b[4;38;5;250;48;5;232mName      Value                                  \x1b[0m\n")
	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	for i, row := range rows {
		color := "\x1b[0;38;5;250;48;5;233m"
		if i%2 == 1 {
			color = "\x1b[0;38;5;250;48;5;232m"
		}
		fmt.Fprintf(tw, "%s%-8s\t%s\x1b[0m\n", color, row[0], row[1])
	}
	_ = tw.Flush()
	if task.Notes != "" {
		fmt.Printf("\nNotes on task %d:\n\x1b[38;5;245m%s\n\x1b[0m\n", task.ID, task.Notes)
	} else {
		fmt.Println()
	}
}
